package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)

	// Read first line (string s)
	if !scanner.Scan() {
		return
	}
	s := scanner.Text()

	// Read second line (list of cards)
	if !scanner.Scan() {
		return
	}
	line := scanner.Text()
	cards := strings.Fields(line)

	found := false
	for _, card := range cards {
		if len(s) >= 2 && len(card) >= 2 {
			if s[0] == card[0] || s[1] == card[1] {
				found = true
				break
			}
		}
	}

	if found {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

